export default "import { useState } from \"react\";\nimport { BiHelpCircle, BiRefresh } from \"react-icons/bi\";\nimport {\n  VuiButtonPrimary,\n  VuiButtonSecondary,\n  VuiFlexContainer,\n  VuiFlexItem,\n  VuiIcon,\n  VuiTab,\n  VuiTabGroup,\n  VuiTabs\n} from \"../../../lib\";\n\nconst tabGroups = [\n  [\"Configure\", \"Data\", \"Query\"],\n  [\"Query histories\", \"Analytics\"]\n];\n\n// Narrow the window to see the groups of tabs collapse into a single tabs navigator before\n// they touch their neighbors.\nexport const Collapsing = () => {\n  const [tab, setTab] = useState(\"Data\");\n\n  return (\n    <VuiFlexContainer fullWidth justifyContent=\"spaceBetween\" alignItems=\"center\" spacing=\"s\">\n      <VuiFlexItem grow={false}>\n        <VuiTabs tabStyle=\"enclosed\">\n          {tabGroups.map((titles, index) => (\n            <VuiTabGroup key={index}>\n              {titles.map((title) => (\n                <VuiTab key={title} isActive={tab === title} onClick={() => setTab(title)}>\n                  {title}\n                </VuiTab>\n              ))}\n            </VuiTabGroup>\n          ))}\n        </VuiTabs>\n      </VuiFlexItem>\n\n      <VuiFlexItem grow={false}>\n        <VuiFlexContainer alignItems=\"center\" spacing=\"xs\">\n          <VuiFlexItem grow={false} shrink={false}>\n            <VuiButtonSecondary\n              color=\"neutral\"\n              size=\"s\"\n              icon={\n                <VuiIcon>\n                  <BiHelpCircle />\n                </VuiIcon>\n              }\n            >\n              Help\n            </VuiButtonSecondary>\n          </VuiFlexItem>\n\n          <VuiFlexItem grow={false} shrink={false}>\n            <VuiButtonSecondary\n              color=\"neutral\"\n              size=\"s\"\n              icon={\n                <VuiIcon>\n                  <BiRefresh />\n                </VuiIcon>\n              }\n            >\n              Reload\n            </VuiButtonSecondary>\n          </VuiFlexItem>\n\n          <VuiFlexItem grow={false} shrink={false}>\n            <VuiButtonPrimary color=\"primary\" size=\"s\">\n              Upload files\n            </VuiButtonPrimary>\n          </VuiFlexItem>\n        </VuiFlexContainer>\n      </VuiFlexItem>\n    </VuiFlexContainer>\n  );\n};\n";