export default "import { BiLinkExternal, BiStar } from \"react-icons/bi\";\nimport {\n  BUTTON_COLOR,\n  VuiIconButton,\n  VuiFlexContainer,\n  VuiFlexItem,\n  VuiIcon,\n  BUTTON_SIZE,\n  VuiSpacer,\n  VuiToggle,\n  VuiText\n} from \"../../../lib\";\nimport { Subsection } from \"../../components/Subsection\";\nimport { useState } from \"react\";\n\nexport const IconButton = () => {\n  const [isDisabled, setIsDisabled] = useState<boolean>(false);\n\n  const icon = (\n    <VuiIcon>\n      <BiStar />\n    </VuiIcon>\n  );\n\n  return (\n    <>\n      <VuiToggle\n        label=\"Disabled (not clickable, visual)\"\n        checked={isDisabled}\n        onChange={() => setIsDisabled(!isDisabled)}\n      />\n\n      <VuiSpacer size=\"m\" />\n\n      <VuiFlexContainer>\n        {BUTTON_COLOR.map((color) => (\n          <VuiFlexItem grow={false} key={color}>\n            <VuiIconButton\n              aria-label=\"Example button\"\n              icon={icon}\n              color={color}\n              isDisabled={isDisabled}\n              onClick={() => console.log(\"click\")}\n              onMouseOver={() => console.log(\"mouse over\")}\n              onMouseOut={() => console.log(\"mouse out\")}\n            />\n          </VuiFlexItem>\n        ))}\n      </VuiFlexContainer>\n\n      <VuiSpacer size=\"s\" />\n\n      <VuiFlexContainer>\n        {BUTTON_SIZE.map((size) => (\n          <VuiFlexItem grow={false} key={size}>\n            <VuiIconButton\n              aria-label=\"Example button\"\n              icon={icon}\n              color=\"primary\"\n              size={size}\n              isDisabled={isDisabled}\n            />\n          </VuiFlexItem>\n        ))}\n      </VuiFlexContainer>\n\n      <VuiSpacer size=\"s\" />\n\n      <Subsection title=\"With selected state\">\n        <VuiFlexContainer>\n          {BUTTON_COLOR.map((color) => (\n            <VuiFlexItem grow={false} key={color}>\n              <VuiIconButton\n                isSelected\n                isDisabled={isDisabled}\n                aria-label=\"Button with selected state\"\n                icon={icon}\n                color={color}\n                onClick={() => console.log(\"click\")}\n                onMouseOver={() => console.log(\"mouse over\")}\n                onMouseOut={() => console.log(\"mouse out\")}\n              />\n            </VuiFlexItem>\n          ))}\n        </VuiFlexContainer>\n      </Subsection>\n\n      <VuiSpacer size=\"s\" />\n      <Subsection title=\"Icon button with link\">\n        <VuiFlexContainer alignItems=\"center\" spacing=\"xs\">\n          <VuiFlexItem>\n            <VuiText>\n              <p>Follow the lint to visit Vectara.com</p>\n            </VuiText>\n          </VuiFlexItem>\n          <VuiFlexItem>\n            <VuiIconButton\n              aria-label=\"icon with link\"\n              color=\"accent\"\n              href=\"https://vectara.com\"\n              target=\"_blank\"\n              isDisabled={isDisabled}\n              icon={\n                <VuiIcon>\n                  <BiLinkExternal />\n                </VuiIcon>\n              }\n            />\n          </VuiFlexItem>\n        </VuiFlexContainer>\n      </Subsection>\n    </>\n  );\n};\n";