export default "import { useRef } from \"react\";\nimport { BiLogOut, BiTransferAlt, BiUser } from \"react-icons/bi\";\nimport {\n  OptionListItem,\n  VuiAccountButton,\n  AccountButtonHandle,\n  VuiButtonSecondary,\n  VuiCopyButton,\n  VuiFlexContainer,\n  VuiFlexItem,\n  VuiIcon\n} from \"../../../lib\";\n\nexport const AccountButton = () => {\n  const accountButtonRef = useRef<AccountButtonHandle>(null);\n\n  const options: OptionListItem<string>[] = [\n    {\n      value: \"switch\",\n      label: \"Switch accounts\",\n      color: \"primary\",\n      testId: \"switchOption\",\n      icon: (\n        <VuiIcon>\n          <BiTransferAlt />\n        </VuiIcon>\n      )\n    },\n    {\n      value: \"signOut\",\n      label: \"Sign out\",\n      color: \"primary\",\n      testId: \"signOutOption\",\n      icon: (\n        <VuiIcon>\n          <BiLogOut />\n        </VuiIcon>\n      )\n    }\n  ];\n\n  const info: { title: string; value: React.ReactNode }[] = [\n    {\n      title: \"Customer ID\",\n      value: (\n        <VuiFlexContainer spacing=\"xs\" alignItems=\"center\">\n          <VuiFlexItem grow={false}>6327476328432</VuiFlexItem>\n\n          <VuiFlexItem>\n            <VuiCopyButton size=\"xs\" value=\"6327476328432\" />\n          </VuiFlexItem>\n        </VuiFlexContainer>\n      )\n    }\n  ];\n\n  return (\n    <VuiAccountButton\n      ref={accountButtonRef}\n      userName=\"Falcor\"\n      email=\"falcor@neverendingstory.com\"\n      options={options}\n      info={info}\n      after={\n        <div style={{ paddingTop: \"12px\" }}>\n          <VuiButtonSecondary\n            fullWidth\n            size=\"s\"\n            color=\"neutral\"\n            onClick={() => accountButtonRef.current?.closeMenu()}\n            icon={\n              <VuiIcon>\n                <BiUser />\n              </VuiIcon>\n            }\n          >\n            Manage account\n          </VuiButtonSecondary>\n        </div>\n      }\n    />\n  );\n};\n";